   173  static int cmp_relo_by_insn_idx(const void *key, const void *elem)
   174  {
   175          size_t insn_idx = *(const size_t *)key;
   176          const struct reloc_desc *relo = elem;
   177
   178          if (insn_idx == relo->insn_idx)
   179                  return 0;
   180          return insn_idx < relo->insn_idx ? -1 : 1;
