   183  static struct reloc_desc *find_prog_insn_relo(const struct bpf_program *prog, size_t insn_idx)
   184  {
   185          return bsearch(&insn_idx, prog->reloc_desc, prog->nr_reloc,
   186                         sizeof(*prog->reloc_desc), cmp_relo_by_insn_idx);
