   189  static int append_subprog_relos(struct bpf_program *main_prog, struct bpf_program *subprog)
   190  {
   191          int new_cnt = main_prog->nr_reloc + subprog->nr_reloc;
   192          struct reloc_desc *relos;
   193          int i;
   194
   195          if (main_prog == subprog)
   196                  return 0;
   197          relos = libbpf_reallocarray(main_prog->reloc_desc, new_cnt, sizeof(*relos));
   198          if (!relos)
   199                  return -ENOMEM;
   200          memcpy(relos + main_prog->nr_reloc, subprog->reloc_desc,
   201                 sizeof(*relos) * subprog->nr_reloc);
   202
   203          for (i = main_prog->nr_reloc; i < new_cnt; i++)
   204                  relos[i].insn_idx += subprog->sub_insn_off;
   205          /* After insn_idx adjustment the 'relos' array is still sorted
   206           * by insn_idx and doesn't break bsearch.
   207           */
   208          main_prog->reloc_desc = relos;
   209          main_prog->nr_reloc = new_cnt;
   210          return 0;
   211  }
