   339  /*
   340   * Relocate sub-program calls.
   341   *
   342   * Algorithm operates as follows. Each entry-point BPF program (referred to as
   343   * main prog) is processed separately. For each subprog (non-entry functions,
   344   * that can be called from either entry progs or other subprogs) gets their
   345   * sub_insn_off reset to zero. This serves as indicator that this subprogram
   346   * hasn't been yet appended and relocated within current main prog. Once its
   347   * relocated, sub_insn_off will point at the position within current main prog
   348   * where given subprog was appended. This will further be used to relocate all
   349   * the call instructions jumping into this subprog.
   350   *
   351   * We start with main program and process all call instructions. If the call
   352   * is into a subprog that hasn't been processed (i.e., subprog->sub_insn_off
   353   * is zero), subprog instructions are appended at the end of main program's
   354   * instruction array. Then main program is "put on hold" while we recursively
   355   * process newly appended subprogram. If that subprogram calls into another
   356   * subprogram that hasn't been appended, new subprogram is appended again to
   357   * the *main* prog's instructions (subprog's instructions are always left
   358   * untouched, as they need to be in unmodified state for subsequent main progs
   359   * and subprog instructions are always sent only as part of a main prog) and
   360   * the process continues recursively. Once all the subprogs called from a main
   361   * prog or any of its subprogs are appended (and relocated), all their
   362   * positions within finalized instructions array are known, so it's easy to
   363   * rewrite call instructions with correct relative offsets, corresponding to
   364   * desired target subprog.
   365   *
   366   * Its important to realize that some subprogs might not be called from some
   367   * main prog and any of its called/used subprogs. Those will keep their
   368   * subprog->sub_insn_off as zero at all times and won't be appended to current
   369   * main prog and won't be relocated within the context of current main prog.
   370   * They might still be used from other main progs later.
   371   *
   372   * Visually this process can be shown as below. Suppose we have two main
   373   * programs mainA and mainB and BPF object contains three subprogs: subA,
   374   * subB, and subC. mainA calls only subA, mainB calls only subC, but subA and
   375   * subC both call subB:
   376   *
   377   *        +--------+ +-------+
   378   *        |        v v       |
   379   *     +--+---+ +--+-+-+ +---+--+
   380   *     | subA | | subB | | subC |
   381   *     +--+---+ +------+ +---+--+
   382   *        ^                  ^
   383   *        |                  |
   384   *    +---+-------+   +------+----+
   385   *    |   mainA   |   |   mainB   |
   386   *    +-----------+   +-----------+
   387   *
   388   * We'll start relocating mainA, will find subA, append it and start
   389   * processing sub A recursively:
   390   *
   391   *    +-----------+------+
   392   *    |   mainA   | subA |
   393   *    +-----------+------+
   394   *
   395   * At this point we notice that subB is used from subA, so we append it and
   396   * relocate (there are no further subcalls from subB):
   397   *
   398   *    +-----------+------+------+
   399   *    |   mainA   | subA | subB |
   400   *    +-----------+------+------+
   401   *
   402   * At this point, we relocate subA calls, then go one level up and finish with
   403   * relocatin mainA calls. mainA is done.
   404   *
   405   * For mainB process is similar but results in different order. We start with
   406   * mainB and skip subA and subB, as mainB never calls them (at least
   407   * directly), but we see subC is needed, so we append and start processing it:
   408   *
   409   *    +-----------+------+
   410   *    |   mainB   | subC |
   411   *    +-----------+------+
   412   * Now we see subC needs subB, so we go back to it, append and relocate it:
   413   *
   414   *    +-----------+------+------+
   415   *    |   mainB   | subC | subB |
   416   *    +-----------+------+------+
   417   *
   418   * At this point we unwind recursion, relocate calls in subC, then in mainB.
   419   */
   420  static int
   421  bpf_object__relocate_calls(struct bpf_object *obj, struct bpf_program *prog)
   422  {
   423          struct bpf_program *subprog;
   424          int i, err;
   425
   426          /* mark all subprogs as not relocated (yet) within the context of
   427           * current main program
   428           */
   429          for (i = 0; i < obj->nr_programs; i++) {
   430                  subprog = &obj->programs[i];
   431                  if (!prog_is_subprog(obj, subprog))
   432                          continue;
   433
   434                  subprog->sub_insn_off = 0;
   435          }
   436
   437          err = bpf_object__reloc_code(obj, prog, prog);
   438          if (err)
   439                  return err;
   440
   441
   442          return 0;
   443  }
